{
  "name": "btlp_event_queue_process",
  "confidence": "medium",
  "docstring": "Processes queued Bluetooth low-power event entries by updating the state word referenced by each entry, clearing the associated IRQ when a global status word is negative, entering btlp sleep for entries without the processing flag, and returning to system initialization when the queue empties.",
  "subsystem": "bt",
  "var_renames": {
    "a2": "event_queue",
    "v2": "global_status_ptr",
    "v6": "first_entry",
    "v7": "ctx_state_value",
    "v8": "entry",
    "v9": "entry_ctx",
    "v10": "next_entry"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "entry flag/state; zero causes btlp_enter_sleep() for this entry"
    },
    {
      "offset": 68,
      "meaning": "entry selector flag; nonzero selects 0x7C000000 for the linked context state word"
    },
    {
      "offset": 76,
      "meaning": "pointer to the associated context/state object whose offset 4 word is updated"
    }
  ]
}
